files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #feafe8;
}

.cat-button {
  display: block;
  width: 100%;
  border: 1px solid black;
  padding: 15px;
  font-weight: 800;
  font-size: 18px;
  text-align: center;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #fff;
}

.cat-title {
  font-weight: 800;
  font-size: 1.5rem;
  text-align: center;
  text-transform: uppercase;
}

.cat-text {
  margin: 25px 0;
}

.parent {
  display: flex;
  justify-content: center;
  align-items: stretch;
}

.content {
  max-width: 40%;
  min-width: 200px;
  display: flex;
  flex-direction: column;
  justify-content: end;
  border: 1px solid;
  padding: 20px;

  /* Код здесь */
}

.cat-image {
  max-height: 600px;
  height: 80vh;
  max-width: 600px;
  border: 1px solid;
  border-left: none;
  object-fit: cover;

  /* И здесь */
}
